// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2023, "10-11", [{"author":"И. Иткин","question":"В стихотворении Николая Заболоцкого есть слова <em>печаль моя, _____</em>. Какое географическое название пропущено?","choices":["<em>Тулуза</em> (город во Франции)","<em>Науру</em> (государство в Океании)","<em>Онтарио</em> (озеро в Северной Америке)","<em>Руфиджи</em> (река на востоке Африки)","<em>Тоскана</em> (область в Италии)."],"key":"Д","review":["Топоним у Заболоцкого","В подсказке «печаль моя» слышится слово «тоска». Найди название места, которое начинается с такого же сочетания звуков.","У Заболоцкого географическое название — «Тоскана». Поэт сближает название итальянской области со словом «тоска»."]},{"author":"А. Панина","question":"Какое из слов: <em>беспристрастный</em>, <em>непредвзятый</em>, <em>безапелляционный</em> и <em>объективный</em> — не синонимично остальным?","choices":["<em>беспристрастный</em>","<em>непредвзятый</em>","<em>безапелляционный</em>","<em>объективный</em>","все слова синонимичны друг другу."],"key":"В","review":["Близкие прилагательные","«Беспристрастный», «непредвзятый» и «объективный» описывают того, кто судит без предубеждения или личной заинтересованности.","«Безапелляционный» значит не допускающий возражений. Уверенность в своей правоте — другой признак, поэтому слово лишнее."]},{"author":"И. Иткин","question":"Современная форма <em>надо</em> — результат сокращения исходной более длинной формы. Какая согласная буква стояла в этой исходной форме после <em>о</em>?","choices":["<em>б</em>","<em>в</em>","<em>ж</em>","<em>й</em>","<em>м</em>."],"key":"А","review":["Старая форма слова «надо»","В старом обороте «мне надобно» можно заменить второе слово на «надо», не меняя смысла.","В полной форме «надобно» сразу после О стоит Б. При сокращении эта часть слова отпала."]},{"author":"А. Сомин","question":"Образуем с помощью суффиксов все возможные прилагательные от приведённых ниже существительных. От какого существительного образуется прилагательное с самой длинной частью после корня?","choices":["<em>река</em>","<em>болото</em>","<em>озеро</em>","<em>море</em>","<em>океан</em>."],"key":"Д","review":["Прилагательные о водоёмах","Выпиши распространённые образования: «речной», «болотный», «болотистый», «озёрный», «морской». Сравни части после корней.","От «океан» получаются «океанский» и «океанический». У «океанического» после корня стоит более длинная часть «-ический». Значит, выбираем «океан»."]},{"author":"И. Рубанов","question":"Если человек хмыкнул, то чего он точно не выразил?","choices":["удивления","сомнения","ужаса","иронии","досады."],"key":"В","review":["О чём говорит «хмыкнул»","Короткое «хм» может выражать сомнение, досаду, удивление или иронию. Подставь его в разные реплики.","Ужас обычно выражают испуганным криком или возгласом. Нейтральное «хм» само по себе такой реакции не передаёт."]},{"author":"Б. Иомдин","question":"В какой паре одно из слов не существует?","choices":["<em>иже — ниже</em>","<em>икнуть — никнуть</em>","<em>изложить — низложить</em>","<em>извести — низвести</em>","<em>изничтожить — низничтожить</em>."],"key":"Д","review":["Глаголы и начало слова","«Иже» встречается в обороте «и иже с ним», а «никнуть» означает наклоняться или опускаться. «Низложить» и «низвести» тоже существуют.","«Изничтожить» — усиленное «уничтожить». Глагола «низничтожить» с начальным Н в русском языке нет."]},{"author":"А. Сомин","question":"В каком из этих слов не тот корень, что в других, а омонимичный ему?","choices":["<em>оплата</em>","<em>доплата</em>","<em>заплата</em>","<em>зарплата</em>","<em>бесплатный</em>."],"key":"В","review":["Плата и заплата","Оплата, доплата, зарплата и бесплатный связаны с деньгами или другим вознаграждением за что-то.","Заплата — кусок ткани, которым закрывают дыру. Здесь другой корень, связанный с тканью, а не с платой."]},{"author":"Л. Фёдорова","question":"Характеризуя Евгения Онегина, А. С. Пушкин пишет:\n<em>Высокой страсти н_ имея\nДля звуков жизни н_ щадить,\nН_ мог он ямба от хорея,\nКак мы н_ бились, отличить.</em>\nВ какой из строчек употреблена не такая частица, как в остальных трёх строчках?","choices":["в первой","во второй","в третьей","в четвёртой","во всех строчках употреблена одна и та же частица."],"key":"Г","review":["Частицы в стихах","«Не имея», «не щадить» и «не мог» содержат обычное отрицание при глаголе или деепричастии.","В строке «Как мы ни бились» речь о том, что усилия были, но не помогли. Это уступительная конструкция, в которой нужна частица «ни»."]},{"author":"А. Сомин","question":"Одно из приведённых ниже названий заведений состоит из двух корней, второй из которых означает ‘дом’ в языке, из которого это слово заимствовано. О каком названии идёт речь?","choices":["<em>ресторан</em>","<em>трактир</em>","<em>таверна</em>","<em>чайхана</em>","<em>харчевня</em>."],"key":"Г","review":["Заведение, где пьют чай","Из названий можно выделить знакомый русский корень «чай» в слове «чайхана». Осталось понять роль второй части.","В заимствованном слове «хана» восходит к персидскому названию дома. «Чайхана» буквально означает чайный дом."]},{"author":"О. Подлесская","question":"Какое словосочетание сильно отличается по смыслу от остальных четырёх?","choices":["<em>горные вершины</em>","<em>лесные тропинки</em>","<em>пустынные улицы</em>","<em>равнинные леса</em>","<em>таёжные реки</em>."],"key":"В","review":["Признаки местности","Горные вершины относятся к горам, лесные тропинки — к лесу, равнинные леса — к равнине, таёжные реки — к тайге.","«Пустынные улицы» обычно находятся не в пустыне. Прилагательное означает, что на улицах нет людей."]},{"author":"И. Рубанов","question":"Поэт Дмитрий Минаев писал:\n<em>Без раздумья, без отсрочки\nЯ бегу к строке от строчки,\nДаже к финским скалам _____\nОбращаясь с каламбуром.</em>\nКакое слово здесь пропущено?","choices":["<em>бурым</em>","<em>каурым</em>","<em>понурым</em>","<em>смурым</em>","<em>хмурым</em>."],"key":"А","review":["Каламбур Минаева","Заметь, что концовка «с каламбуром» может подсказать не только рифму, но и стык слов в предыдущей строке.","«К скалам бурым» даёт на стыке «скалам» и «бурым» почти те же звуки, что «с каламбуром». Подходит «бурым»."]},{"author":"А. Пиперски","question":"Какое (какие) из слов <em>жиром</em>, <em>сыром</em>, <em>паром</em>, <em>шаром</em> и <em>даром</em> можно прочитать с двумя разными ударениями?","choices":["только <em>сыром</em>","только <em>сыром</em> и <em>паром</em>","только <em>сыром</em>, <em>паром</em> и <em>шаром</em>","все, кроме <em>жиром</em>","все."],"key":"В","review":["Два варианта ударения","Сравни «сы́ром» из «с сыром» и «сыро́м» из «в сыром виде». У «па́ром» от «пар» и «паро́м» как названия переправы тоже разные ударения.","«Ша́ром» обычно называют форму или предмет, а в обороте «шаро́м покати» ударение иное. «Жи́ром» и «да́ром» второго нормативного ударения не дают."]},{"author":"Б. Иомдин","question":"Одно латинское прилагательное, означающее ‘врождённый, естественный, натуральный’, во французском языке потеряло согласный в корне, стало значить ‘не имеющий жизненного опыта’ и в таком виде было заимствовано в русский язык, где часто относится к людям, глазам и вопросам. А какой это был согласный?","choices":["b","n","r","s","t."],"key":"Д","review":["Путь слова «наивный»","Русское «наивный» пришло из французского. Сопоставь французское «naïf» со старым латинским «nativus» со значением врождённого.","Между А и И в латинском слове было t. Во французской форме этот согласный исчез, откуда и его отсутствие в русском слове."]},{"author":"П. Долгополов","question":"Русская песня «Проводы» стала считаться народной, хотя известно, что исходное стихотворение написал поэт Демьян Бедный. Вот начало народной версии:\n<em>Как родная меня мать провожала,\nТут и вся моя родня набежала.\nА куда ж ты, паренёк, а куда ты?\nНе ходил бы ты, Ванёк, во солдаты.\nВ Красной Армии штыки, чай, найдутся,\nБез тебя большевики обойдутся.</em>\nКак начиналось стихотворение Демьяна Бедного?","choices":["<em>Как родная меня мать провожала,\nКак тут вся родня моя набежала.</em>","<em>Как родная мать меня провожала,\nКак тут вся моя родня набежала.</em>","<em>Как родная мать меня провожала,\nКак тут вся родня моя набежала.</em>","<em>Как меня родная мать провожала,\nКак тут вся моя родня набежала.</em>","<em>Как меня родная мать провожала,\nКак тут вся родня моя набежала.</em>"],"key":"Б","review":["Стихотворение и песня","В песне расстановка слов изменилась. Поэтому сравни выражение «родная меня мать» с прямым порядком «родная мать меня».","В исходном стихотворении дальше идёт «Как тут вся моя родня набежала». Из предложенных начал две строки в этом порядке содержит только вариант Б."]},{"author":"А. Пиперски","question":"Дан фрагмент из романа Ф. М. Достоевского «Преступление и наказание»: <em>В последнее время она стала всё чаще и больше разговаривать с своею старшею девочкой, десятилетнею Поленькой, которая хотя и многого ещё не понимала, но зато очень хорошо поняла, что нужна матери, и потому всегда следила за ней своими большими умными глазками и всеми силами хитрила, чтобы представиться всё понимающею.</em> Заполните пропуски ещё в одном фрагменте из этого романа: <em>Мебель, вся очень старая и из жёлтого дерева, состояла из дивана с огромно_ выгнуто_ деревянно_ спинко_, круглого стола овально_ формы перед диваном,</em> …","choices":["<em>й</em>, <em>й</em>, <em>й</em>, <em>й</em>, <em>й</em>","<em>й</em>, <em>й</em>, <em>й</em>, <em>ю</em>, <em>й</em>","<em>ю</em>, <em>ю</em>, <em>ю</em>, <em>й</em>, <em>ю</em>","<em>ю</em>, <em>ю</em>, <em>ю</em>, <em>й</em>, <em>й</em>","<em>ю</em>, <em>ю</em>, <em>ю</em>, <em>ю</em>, <em>ю</em>."],"key":"Г","review":["Окончания двух падежей","У Достоевского встречается длинная форма творительного падежа прилагательных: «своею старшею ... десятилетнею». После «с» можно написать «огромною выгнутою деревянною».","Дальше идут существительное «спинкой» и родительный падеж «овальной формы». Получаются три Ю, затем две Й."]},{"author":"О. Подлесская","question":"Какое устойчивое выражение написано правильно?","choices":["<em>Вавилонское толпотворение</em>","<em>глаз вопиющего в пустыне</em>","<em>гиена огненная</em>","<em>камень преткновения</em>","<em>колос на глиняных ногах</em>."],"key":"Г","review":["Как пишется выражение","В устойчивых выражениях говорят «столпотворение», «глас вопиющего», «геенна огненная» и «колосс на глиняных ногах». Сравни эти формы с вариантами.","«Камень преткновения» — препятствие, вызывающее затруднение или спор. В этом варианте все слова переданы правильно."]},{"author":"А. Пиперски","question":"Даны турецкие названия частей речи: sıfat ‘прилагательное’, fiil ‘глагол’, zarf ‘наречие’, bağlaç ‘союз’ (ı читается как русское <em>ы</em>, ç — как <em>ч</em>, ğ не читается). Как будет по-турецки ‘деепричастие’?","choices":["sıfat-zarf","fiil-bağlaç","zarf-fiil","bağlaç-sıfat","sıfat-fiil."],"key":"В","review":["Часть речи по-турецки","Деепричастие образуется от глагола, а в предложении часто отвечает на вопрос «как?» или «когда?», то есть выполняет роль наречия.","Совмещаем турецкие «zarf» — «наречие» и «fiil» — «глагол». Получается «zarf-fiil»."]},{"author":"Б. Иомдин","question":"Читаем у Михаила Шолохова в «Поднятой целине»: — <em>Люди <strong>роптают</strong> против колхозов и против сдачи хлеба.</em> А как должен выглядеть выделенный глагол в литературном языке?","choices":["так и должен: <em>роптают</em>","<em>ропотают</em>","<em>ропочут</em>","<em>ропщут</em>","такого глагола в литературном языке нет."],"key":"Г","review":["Литературная форма глагола","Начальная форма глагола — «роптать», то есть выражать недовольство. Чтобы проверить форму, вспомни первое лицо «я ропщу».","В третьем лице множественного числа будет «они ропщут». В литературной речи пишется Щ, как и в «ропщу»."]},{"author":"А. Пиперски","question":"<em>У него температура под _____</em> — с каким числительным эта фраза встречается реже всего?","choices":["<em>сорок один</em>","<em>сорок</em>","<em>тридцать девять</em>","<em>тридцать восемь</em>","<em>тридцать семь</em>."],"key":"Д","review":["Как говорят о температуре","«У него температура» обычно означает, что у человека жар. «Под» приблизительно указывает на значение немного ниже названного.","Температура немного ниже 37° близка к обычной. Поэтому «под тридцать семь» в сообщении о жаре встречается реже остальных."]},{"author":"А. Сомин","question":"В каком предложении на месте пропуска нужно вставить не ту букву, что в других?","choices":["<em>Чарлза поместили на квартиру к одной бедной женщине, державшей п_нсионеров и послужившей впоследствии прототипом миссис Пипчинс в «Домби и сыне».</em> (А. Анненская)","<em>― Странно, ― говорю я, ни к кому не обращаясь, ― собак выгуливают вечером или ранним утром, а сейчас полдень ― Ничего странного, ― отвечает мне кто-то, стоящий рядом, ― в городе полно п_нсионеров, и они могут выгуливать собак, когда им заблагорассудится.</em> (Г. Алексеев)","<em>Всё на своём месте, только я теперь заметил, как я вырос, сравнивая себя теперь с тем временем, когда я был п_нсионером.</em> (В. Гаршин)","<em>Так, в этом доме проявились самые различные интересы его обитателей, и своих, и п_нсионеров.</em> (А. Тахо-Годи)","<em>Вдруг из класса с шумом и смехом выбежало несколько п_нсионеров.</em> (Н. Позняков)"],"key":"Б","review":["«Пансионер» и «пенсионер»","Человек может жить за плату в пансионе или учиться в закрытой школе. Такое лицо называли «пансионером», с буквой А в первом слоге.","Люди, получающие пенсию и гуляющие с собаками в середине дня, — «пенсионеры», с Е. Буква отличается во втором отрывке."]},{"author":"А. Пиперски","question":"В русском языке есть устойчивое выражение, в котором слово <em>ворота</em> можно заменить на слово _____.","choices":["<em>двери</em>","<em>калитки</em>","<em>входы</em>","<em>форточки</em>","<em>рамки</em>."],"key":"Д","review":["За пределами допустимого","«Ни в какие ворота не лезет» говорят, когда поступок или утверждение совершенно неприемлемы.","Образ можно передать как выход за рамки допустимого. Говорят «ни в какие рамки не лезет». Подходит слово «рамки»."]},{"author":"И. Иткин","question":"Основное население бразильского города Нову-Амбургу первоначально составляли выходцы из _____.","choices":["Болгарии","Германии","Испании","Италии","Чили."],"key":"Б","review":["Откуда переселенцы","«Нову» означает «новый». Значит, в названии бразильского города слышится название другого города, память о родных местах переселенцев.","«Амбургу» передаёт «Гамбург». Этот город находится в Германии, откуда и приехали первые жители."]},{"author":"И. Рубанов и С. Переверзева","question":"На уроке русского языка учительница сказала: «Представьте себе, что слово <em>кре́чет</em> — это не название хищной птицы, а глагол в форме 3 лица ед. числа наст. времени. Как в таком случае могла бы выглядеть его неопределённая форма?». Аня ответила <em>крекать</em>, Боря — <em>кретать</em>, Вова — <em>кречь</em>, а Дима — <em>кречать</em>. Кто из ребят точно ошибся?","choices":["Аня и Боря","Боря и Вова","Вова и Дима","Дима и Аня","все ответили правильно."],"key":"В","review":["Воображаемый глагол","У «крекать» возможна модель «плакать — плачет», у «кретать» — «метать — мечет». Обе дают согласную Ч в личной форме.","От «кречь» по модели «печь — печёт» ожидалось бы «кречёт», с ударным окончанием. «Кречать» по типу «кричать» дало бы «кречит» или по типу «качать» — «кречает». Вова и Дима не подходят."]},{"author":"О. Подлесская","question":"В какой из этих пяти фраз глагол <em>парировать</em> употреблён правильно?","choices":["<em>Вместо того, чтобы грамотно парировать с оппонентом, Вы переходите на оскорбления.</em>","<em>У меня не хватает аргументов, чтобы парировать твоим блистательным доводам</em>.","<em>Организаторы научились парировать нападки недоброжелателей</em>.","<em>Но ему одному трудно парировать против вас двоих</em>.","<em>Также могу парировать к Вам Вашими просьбами</em>."],"key":"В","review":["Управление глагола","«Парировать» значит отбить удар или успешно ответить на возражение. Оно требует прямого дополнения: парировать что?","В варианте «парировать нападки недоброжелателей» дополнение в винительном падеже без предлога. Остальные примеры смешивают это управление с другими глаголами."]},{"author":"О. Подлесская","question":"В старом анекдоте пропущены два разных слова. Эти слова исторически являются однокоренными. Догадавшись, какое слово пропущено первым, восстановите второе. <em>— Какая разница между стихотворениями прежних и нынешних поэтов? — В прежних стихотворениях звучала _____, а в нынешних — _____.</em>","choices":["<em>дудка</em>","<em>балалайка</em>","<em>скрипка</em>","<em>гармошка</em>","<em>труба</em>."],"key":"Г","review":["Старинный анекдот","Первые поэты создавали гармонию — согласованное, красивое звучание. В анекдоте от высокого слова нужно перейти к названию простого инструмента.","Слово «гармошка» относится к той же семье, что «гармоника» и «гармония». Так шутка связывает высокий стиль с музыкальным инструментом."]},{"author":"С. Дьяченко","question":"Какое из этих слов произошло от предлога?","choices":["<em>обойма</em>","<em>сквозной</em>","<em>последний</em>","<em>возлежать</em>","<em>прелый</em>."],"key":"Б","review":["Слово из предлога","Поищи в слове основу, которая сама употребляется перед существительным. «Сквозь» — предлог, например «сквозь стену».","От него образовано «сквозной», то есть проходящий насквозь. Поэтому подходит это прилагательное."]},{"author":"А. Пиперски","question":"Какое слово употребляется почти исключительно с предлогом <em>в</em>?","choices":["<em>бытие</em>","<em>бытовка</em>","<em>бытование</em>","<em>быт</em>","<em>бытность</em>."],"key":"Д","review":["Сочетание «в бытность»","«Быт», «бытие», «бытовка» и «бытование» свободно употребляются с несколькими предлогами или без них.","«Бытность» сохранилась в обороте «в бытность мою студентом», то есть «когда я был студентом». Это слово почти всегда имеет перед собой «в»."]},{"author":"А. Пиперски","question":"Какой из прочерков должен быть заполнен не так, как остальные?","choices":["<em>Как будто древний этот вид / Раз _____ запечатлён / В душе, которая хранит / Всю красоту былых времён…</em> (Н. Рубцов)","<em>Подобье птиц, он спит в своём гнезде, / свой чистый путь и жажду жизни лучшей / раз _____ доверив той звезде, / которая сейчас закрыта тучей.</em> (И. Бродский)","<em>Когда тебе мне верить не угодно, / Раз _____ дозволь мне удалиться.</em> (А. К. Толстой)","<em>Раз _____ я тобой покорён / Жить не давала и смерти мешаешь.</em> (Б. Ахмадулина)","<em>Не жалею, не зову, не плачу, / Не кричу, не требую суда. / Потому что так и не иначе / Жизнь сложилась раз _____.</em> (С. Гандлевский)"],"key":"Д","review":["Слово между «раз» и «навсегда»","Прочитай первые четыре отрывка с «раз навсегда». Сочетание без союза сохраняет ритм строк.","В последней строке нужен дополнительный слог: «Жизнь сложилась раз и навсегда». Здесь после «раз» вставляется «и навсегда»."]},{"author":"Б. Иомдин","question":"Из таких, казалось бы, разных слов все, кроме одного, на самом деле восходят к древнееврейскому слову, означающему ‘мешок’. Кроме какого?","choices":["<em>саквояж</em>","<em>сачок</em>","<em>саше</em>","<em>сакля</em>","<em>рюкзак</em>."],"key":"Г","review":["Слова со значением «мешок»","«Саквояж», «сачок», «саше» и «рюкзак» по происхождению содержат названия мешка или сумки. Сравни «сак» и немецкое «Sack».","«Сакля» — название жилища в горах Кавказа. Оно заимствовано из грузинского «сахли», «дом», и не связано с мешком."]},{"author":"А. Пиперски","question":"Даны несколько слов на сербском языке и их русские переводы: <em>врх</em> ‘верх’, <em>око</em> ‘глаз’, <em>жртва</em> ‘жертва’. В переводе какого из данных ниже предложений на сербский язык встретится слово, которое состоит из четырёх подряд идущих букв алфавита?","choices":["<em>Я не знаю, где ёж</em>.","<em>Видит око, да зуб неймёт.</em>","<em>Авиакомпания KLM возобновила полёты из Амстердама в Белград</em>.","<em>На верху горы качается верба.</em>","<em>Аня порезала палец ножом.</em>"],"key":"Д","review":["Сербское слово из четырёх букв","Сравни русские «верх», «жертва» и сербские «врх», «жртва». В сербском в таких сочетаниях Р может образовать слог без гласной перед ним.","«Палец» по-сербски «прст». В сербской кириллице П, Р, С и Т идут подряд. Это слово будет в предложении про порезанный палец."]}], {"year":2023,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2023-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
